export const dropdownOptions=[['styles of dance','sizes of class'],['special one-on-one dance classes','a fun mix of exercise and dance in the class'],['register online','go to their office'],['try all the trial classes','ask the staff for advice']];
export const dropdownSentences=[['1. QDC offers four different levels of classes and has different ',' in those levels.'],['2. For those who have never taken a dance class, there is nothing to worry about, because they will have ','.'],['3. If you want to sign up, you can ','.'],['4. You should ',' before registration to figure out what styles you might be interested in and what level you want to dance at.']];
// Synthetic transcript and grading for offline tests, not the course's answer key.
export const dropdownAnswers=dropdownOptions.map(options=>options[0]);
export const dropdownTranscript='Offline test material. For each sentence, the first listed expression is the fixture answer. This text only verifies extraction, answer filling, and complete-exercise banking.';
const escape=value=>value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function dropdownMarkup({reverse=false,draft=''}={}){
  return '<div class="question-common-abs-scoop comp-scoop-reply comp-scoop-reply-dropdown-selection-overflow"><div class="item"><div class="component-htmlview">'+dropdownSentences.map(([start,end],i)=>'<div class="sentence">'+escape(start)+'<span class="fe-scoop" data-scoop-index="'+i+'"><span class="scoop-select-wrapper"><div style="height:0px;visibility:hidden;position:absolute;z-index:-9999">'+(reverse?[...dropdownOptions[i]].reverse():dropdownOptions[i]).map(value=>'<i><p>'+escape(value)+'</p></i>').join('')+'</div><span class="input-wrapper"><span class="ant-dropdown-trigger user-answer'+(draft?'':' empty')+'"><div class="component-htmlview user-answer-text">'+escape(draft||'点击选择')+'</div><span class="select-arrow">⌄</span></span></span></span></span>'+escape(end)+'</div>').join('')+'</div></div></div>';
}
export function dropdownHTML({mode='normal',reverse=false,embedded=true}={}){
  return `<!doctype html><html><body><style>body{font:16px Arial}.sentence{margin:22px}.scoop-select-wrapper{display:inline-block}.user-answer{display:inline-block;min-width:90px;color:#08f;cursor:pointer;border-bottom:1px solid gray}.select-arrow{margin-left:8px}.ant-dropdown{position:fixed;z-index:100;background:white;border:1px solid #aaa}.select-option{padding:8px;cursor:pointer}.ant-dropdown-hidden{display:none}video{width:320px;height:180px}</style>
  <header><div class="pc-break-crumb"><span class="pc-break-crumb-text">Offline book</span><span class="pc-break-crumb-text">Time off</span><span class="pc-break-crumb-text">Viewing and understanding</span></div><div class="pc-header-tab-activity">Viewing and understanding</div><div class="pc-task pc-header-task-activity">Exercise 2</div></header>
  <main class="layout-container"><div class="abs-direction">Watch the video again and complete the following statements by choosing the correct option.</div><div class="layout-material-container"><video src="https://ucontent.unipus.cn/offline-recognition/dropdown-video.webm"></video>${embedded?'<div class="transcript">'+dropdownTranscript+'</div>':''}</div>${dropdownMarkup({reverse})}</main><button id="submit">提交</button>
  <script>const mode=${JSON.stringify(mode)},answers=${JSON.stringify(dropdownAnswers)};window.openCount=0;window.optionClicks=0;window.trustedClicks=[];window.submitted=false;window.savedAnswers=[];
  document.addEventListener('click',event=>{
    const trigger=event.target.closest('.scoop-select-wrapper .ant-dropdown-trigger');
    if(trigger){
      window.openCount++;document.querySelectorAll('.scoop-select-dropdown').forEach(el=>el.classList.add('ant-dropdown-hidden'));
      const wrapper=trigger.closest('.scoop-select-wrapper'),index=wrapper.closest('[data-scoop-index]').getAttribute('data-scoop-index'),rect=wrapper.getBoundingClientRect(),replacement=wrapper.cloneNode(true);replacement.removeAttribute('data-ustudy-control');wrapper.replaceWith(replacement);
      const values=[...replacement.querySelectorAll('i')].map(el=>el.textContent.trim());if(mode==='mismatch')values[0]='An unrelated option';if(mode==='duplicate')values[1]=values[0];
      const popup=document.createElement('div');popup.className='ant-dropdown scoop-select-dropdown';popup.dataset.owner=index;popup.style.left=rect.left+'px';popup.style.top=rect.bottom+'px';const menu=document.createElement('ul');menu.className='ant-dropdown-menu scoop-select';menu.setAttribute('role','menu');
      for(const value of values){const item=document.createElement('li');item.className='ant-dropdown-menu-item select-option';item.setAttribute('role','menuitem');item.setAttribute('aria-disabled',String(mode==='disabled'));const content=document.createElement('span');content.className='ant-dropdown-menu-title-content';content.textContent=mode==='zero-width'?'\\u200b'+value+'\\ufeff':value;item.append(content);menu.append(item);}popup.append(menu);document.body.append(popup);
      if(mode==='appear'){popup.style.transform='scaleY(0)';popup.style.opacity='0';setTimeout(()=>{popup.style.transform='';popup.style.opacity='1';},180);}
      if(mode==='aria-stale'){const stale=popup.cloneNode(true);stale.setAttribute('aria-hidden','true');stale.style.pointerEvents='none';document.body.prepend(stale);}
      if(mode==='changed-stem')document.querySelector('.sentence').firstChild.textContent='A different question ';return;
    }
    const option=event.target.closest('.scoop-select-dropdown .select-option');if(option){window.optionClicks++;window.trustedClicks.push(event.isTrusted);if(option.getAttribute('aria-disabled')==='true')return;const popup=option.closest('.scoop-select-dropdown'),wrapper=document.querySelector('[data-scoop-index="'+popup.dataset.owner+'"] .scoop-select-wrapper'),replacement=wrapper.cloneNode(true),trigger=replacement.querySelector('.user-answer');trigger.classList.remove('empty');trigger.querySelector('.user-answer-text').textContent=option.textContent;replacement.removeAttribute('data-ustudy-control');wrapper.replaceWith(replacement);popup.classList.add('ant-dropdown-hidden');if(mode==='revert')setTimeout(()=>{trigger.classList.add('empty');trigger.querySelector('.user-answer-text').textContent='点击选择';},180);}
  });
  document.getElementById('submit').onclick=()=>{window.savedAnswers=[...document.querySelectorAll('.user-answer')].map(el=>el.classList.contains('empty')?'':el.querySelector('.user-answer-text').textContent);window.submitted=true;const correct=window.savedAnswers.filter((value,i)=>value===answers[i]).length;document.querySelector('main').innerHTML='<h2>答题小结</h2><p>共4道题，客观题4道，主观题0道</p><p>正确 ('+correct+'/4)</p><p>错误 ('+(4-correct)+'/4)</p><p>部分正确 (0/4)</p><p>未作答 0</p>';document.getElementById('submit').remove();};
  </script></body></html>`;
}
